INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c6576b7e-5283-4d31-bbe2-956f7f573c9e', '21feff02-016d-46e2-bb9d-c27495133b1b', '51. óra: A kör', 'A kör elemei: középpont (O), sugár (r), átmérő (d), húr, körív, körző használata.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "30c4975c-91df-4136-a959-0af1ed85ef00", "text": "Hogyan viszonylik a kör átmérője (d) a sugárhoz (r)?", "type": "multiple-choice", "options": [{"id": "7746be2f-d85f-4b9b-86a4-e42d123920fa", "text": "d = 2 * r (az átmérő a sugár kétszerese)", "isCorrect": true}, {"id": "6c84b3fd-eede-48d4-8b2a-83bc2c3583f6", "text": "d = r / 2", "isCorrect": false}, {"id": "4d3d90a6-2e41-4415-bf43-8a5a44aeeeca", "text": "d = r + 5", "isCorrect": false}, {"id": "3d8c3168-3a6d-48dd-9b7d-5c9425b0606f", "text": "d = r * r", "isCorrect": false}], "timeLimit": 15}, {"id": "f6d77060-9e88-461d-8a5a-059ccb51e173", "text": "Ha a kör sugara r = 5 cm, mennyi az átmérője (d)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "0e881029-c07a-4591-8dd9-6d9b5ca14cd3", "text": "Ha a kör átmérője d = 16 cm, mennyi a sugara (r)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "82d65e70-13de-4737-ab99-52cd625acdee", "text": "A körvonal pontjai a középponttól egyenlő távolságra (sugárnyira) vannak.", "type": "true-false", "options": [{"id": "f1b608be-e9db-4773-9ccd-42aad54dbdb9", "text": "Igaz", "isCorrect": true}, {"id": "15ea49cc-0b2c-4bc1-97f5-7329d33bc6c9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "84984d0f-0f44-4f06-8a7a-2268a305c2dc", "text": "Mi a kör leghosszabb húrja?", "type": "multiple-choice", "options": [{"id": "f46f6039-3d6d-4039-ab8f-af00623b1b40", "text": "Az átmérő", "isCorrect": true}, {"id": "31c2f32b-07d8-4685-9443-afe52fcc9089", "text": "A sugár", "isCorrect": false}, {"id": "57f8f8b7-2d48-4df7-8488-e15cb7e861f3", "text": "A körív", "isCorrect": false}, {"id": "7bdef879-3d28-4de5-8fa4-f10907f58334", "text": "A körcikk", "isCorrect": false}], "timeLimit": 15}, {"id": "e397c20c-6e04-4c71-ad09-b179e0e8d271", "text": "A körző a körök rajzolására és távolságok másolására szolgáló szerkesztőeszköz.", "type": "true-false", "options": [{"id": "d868648c-eb4d-40ec-aa0b-044171d2be6d", "text": "Igaz", "isCorrect": true}, {"id": "9384fa73-26e5-45c1-b980-8c69bb8ff391", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bf8ca06c-813e-4729-b25f-adf18164e7a9", "text": "A kör belsejében lévő pontok távolsága a középponttól kisebb, mint a sugár.", "type": "true-false", "options": [{"id": "7711fc74-ce15-4711-abdf-0d5dc88080db", "text": "Igaz", "isCorrect": true}, {"id": "cb114b42-a821-40de-a8ec-6f5a470264d1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('46eda781-40a9-49c9-842f-7bc8dbfc08d9', '21feff02-016d-46e2-bb9d-c27495133b1b', '52. óra: A szakasz felezőmerőlegese', 'A szakaszfelező merőleges tulajdonságai, szerkesztése körzővel és vonalzóval.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "a136b1b2-7e5d-40e9-95cf-2caa55a2e489", "text": "Mi a szakaszfelező merőleges egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "b0093246-67d0-4b0a-9103-eed947c2b5d3", "text": "A szakasz felezőpontján áthaladó, a szakaszra merőleges egyenes, melynek pontjai egyenlő távolságra vannak a szakasz két végpontjától", "isCorrect": true}, {"id": "2fc0a36b-e762-48f8-8898-e7240ba210c8", "text": "A szakasszal párhuzamos egyenes", "isCorrect": false}, {"id": "f9a3ccb3-5517-4e28-a87e-3a525d7d53cb", "text": "A szakasz egyik végpontján átmenő egyenes", "isCorrect": false}, {"id": "0b27cff2-a086-4198-8382-1bf38f67586c", "text": "Minden szakaszhoz 2 felezőmerőleges tartozik", "isCorrect": false}], "timeLimit": 15}, {"id": "38064baa-7eab-4776-8196-599be1d64131", "text": "Hány felezőmerőlegese van egy szakasznak a síkban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "d7f9ebb1-a313-4860-bbf4-838c3f2665e3", "text": "A szakaszfelező merőleges egyenes pontjai egyenlő távolságra vannak a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "39851ab6-1dbb-40d1-a50d-49fe39bd6616", "text": "Igaz", "isCorrect": true}, {"id": "0de6ae77-f88b-4238-8fa1-62e7707d74f4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7afef074-c0e1-4e2e-82a1-bff2afbb0fca", "text": "A szakasz felezőmerőlegesének megszerkesztéséhez a szakasz felénél nagyobb körzőnyílás szükséges.", "type": "true-false", "options": [{"id": "f98014a4-c68e-4c08-a1ed-245c15207835", "text": "Igaz", "isCorrect": true}, {"id": "2963ec51-236f-45bb-ac38-765eaa14205c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a6bdd037-214c-4a90-b3c9-91250f4990d5", "text": "Hány fokos szöget zár be a felezőmerőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "ecfe3054-eac6-4918-bd53-4b5683b30d3e", "text": "A háromszög oldalfelező merőlegesei egy pontban metszik egymást (a körülírt kör középpontjában).", "type": "true-false", "options": [{"id": "423e82de-8366-47a5-afda-c7f62c8d61f6", "text": "Igaz", "isCorrect": true}, {"id": "2aaf94e2-5266-435e-8e3d-79339686ac3c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bdab7c1e-d1db-4494-9f7f-455cb72fb988", "text": "Egy 8 cm-es szakasz felezőpontja a végponttól 4 cm-re van.", "type": "true-false", "options": [{"id": "516c2d81-9a08-4b5d-8c9e-bf950386cb42", "text": "Igaz", "isCorrect": true}, {"id": "46bf9064-0781-4c3f-a2f9-9dab03a85404", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4f3f8625-b0be-4dfc-8c7d-b9bfd9ba3654', '21feff02-016d-46e2-bb9d-c27495133b1b', '53. óra: Szerkesztések', 'Alapszerkesztések: szakasz másolása, szög másolása, merőleges és párhuzamos állítása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "a390972d-2243-4452-91ae-b4f8ed127090", "text": "Milyen eszközt használunk körök és ívek rajzolásához szerkesztéskor?", "type": "multiple-choice", "options": [{"id": "dc3035ee-1cc6-40f1-b014-d0c145c45fd0", "text": "Körzőt", "isCorrect": true}, {"id": "cf216e8f-3c7f-40ae-8fc0-35c5cdfb0a8e", "text": "Szögmérőt", "isCorrect": false}, {"id": "9d8f1535-730b-4afd-a7cc-5b6fb9439393", "text": "Radírt", "isCorrect": false}, {"id": "62061896-4a7d-46b4-a629-b96571c14feb", "text": "Tollat", "isCorrect": false}], "timeLimit": 15}, {"id": "99bc46aa-27e4-43ce-b01b-3dd0aa5e8bef", "text": "Milyen vonalzót használunk a tiszta geometrikai szerkesztésekhez?", "type": "multiple-choice", "options": [{"id": "a3071de0-b58c-4851-976b-9820da406de8", "text": "Beosztás nélküli (egyenes) vonalzót", "isCorrect": true}, {"id": "7eab0925-386a-448f-9a5e-18b81dac79ee", "text": "Derékszögű vonalzót beosztással", "isCorrect": false}, {"id": "e3d3f5fe-a836-459a-9c60-3cca4366ba7b", "text": "Görbe vonalzót", "isCorrect": false}, {"id": "fede99f4-97d3-47c1-bdea-7dc885b0b753", "text": "Mérőszalagot", "isCorrect": false}], "timeLimit": 15}, {"id": "7f29f9a7-2bbc-42d0-81ea-d4b16450bafa", "text": "Szakasz másolásakor körzővel mérjük fel a szakasz hosszát.", "type": "true-false", "options": [{"id": "47d96e10-a905-4720-bb6d-19127a1ff161", "text": "Igaz", "isCorrect": true}, {"id": "c0e6ad6a-9849-4f14-88d6-e0ac16fc2d2a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "726d1567-543d-48c7-9995-328489342b6f", "text": "A szerkesztéseknél a körzőívek metszéspontjai adják meg a keresett pontokat.", "type": "true-false", "options": [{"id": "a1ec8455-e37c-47dd-8126-b24a30bbdcfe", "text": "Igaz", "isCorrect": true}, {"id": "0b5ae48b-26a2-475f-8e83-87a7019a6dfd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7f35def9-24e6-4803-9190-ffffb066080b", "text": "Hány fokos szöget zár be két egymásra merőleges egyenes?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "b81b06cf-d2ef-4983-909b-4d4fd98495e3", "text": "Két párhuzamos egyenes sehol sem metszi egymást a síkban.", "type": "true-false", "options": [{"id": "dc3c1000-d1c1-4cbe-87e7-aded82ec50ca", "text": "Igaz", "isCorrect": true}, {"id": "5be07239-54d0-4a3e-9c0f-ad921b76f89d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fa250c46-823c-4472-99ae-b86459253674", "text": "A pontos és esztétikus szerkesztés alapkövetelmény a geometriában.", "type": "true-false", "options": [{"id": "2e3f7a15-5240-4870-9146-f5bad7803e4c", "text": "Igaz", "isCorrect": true}, {"id": "cf4edfc8-91f9-46bf-9f06-0f4424d35926", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('102ce0bc-75e2-4b50-931e-8709d4629d79', '21feff02-016d-46e2-bb9d-c27495133b1b', '54. óra: Szerkesztések II.', 'Egyszerű szerkesztési feladatok: háromszög szerkesztése oldalaiból (SSSZ), háromszög-egyenlőtlenség.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "be00a4e6-620e-4b38-8865-f8dbbd09e096", "text": "Mi a háromszög-egyenlőtlenség szabálya?", "type": "multiple-choice", "options": [{"id": "b504559e-77c5-4aa6-a75a-20537aef7d89", "text": "A háromszög bármely két oldalának összege nagyobb a harmadik oldalnál (a + b > c)", "isCorrect": true}, {"id": "88cd3666-aeb3-492f-9551-4b67b8a66d03", "text": "A három oldal összege 180", "isCorrect": false}, {"id": "35027d5b-332e-436a-abea-786708354aa5", "text": "A két rövidebb oldal összege kisebb a harmadiknál", "isCorrect": false}, {"id": "eb44bc3c-25ae-4ac3-a172-7be78128168d", "text": "Minden oldal egyenlő", "isCorrect": false}], "timeLimit": 15}, {"id": "ad441e79-fecd-4d52-adcd-f5e757c112d3", "text": "Szerkeszthető-e háromszög a 3 cm, 4 cm, 8 cm oldalakkal? (3+4 = 7 < 8)", "type": "true-false", "options": [{"id": "651977bf-a5fc-49d6-8d2f-2580cf143d8d", "text": "Igaz", "isCorrect": false}, {"id": "b2063a1a-d8dc-4f0a-ac35-6e206462a5fb", "text": "Hamis (nem teljesül a háromszög-egyenlőtlenség)", "isCorrect": true}], "timeLimit": 15}, {"id": "94912358-5e12-4d91-8b3c-2b08900bc35b", "text": "Szerkeszthető-e háromszög 5 cm, 6 cm, 7 cm oldalakkal?", "type": "true-false", "options": [{"id": "9b4113d4-e987-48d5-98a0-862f6ac4567e", "text": "Igaz (5+6 > 7)", "isCorrect": true}, {"id": "50de41f0-d5ad-441b-8cc7-403dcd2fcdf1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7689c250-f3d5-40bd-94c4-7e2720876b5e", "text": "Hány adatra van szükség legalább egy háromszög egyértelmű megszerkesztéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "cb5f81d0-7805-4de6-b242-92e811b38f2a", "text": "A háromszög szerkesztésének lépései: Vázlat -> Adatok -> Szerkesztés -> Ellenőrzés.", "type": "true-false", "options": [{"id": "c4574b43-76b5-4fdd-9992-cd8bb41ace85", "text": "Igaz", "isCorrect": true}, {"id": "d44e98fd-62f0-4211-bcec-e670274f71fb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "47d631b0-e1f1-4b04-ba04-d57f2790b712", "text": "Szerkeszthető-e háromszög 2 cm, 3 cm, 5 cm oldalakkal? (2+3 = 5)", "type": "true-false", "options": [{"id": "875e367a-6b2a-4e2c-ad8d-ca2323812a70", "text": "Igaz", "isCorrect": false}, {"id": "236ee9b7-756f-41c6-b0f3-fc8190395125", "text": "Hamis (kell hogy > legyen, nem =)", "isCorrect": true}], "timeLimit": 15}, {"id": "0b1f367e-393e-43e7-b300-426614be074e", "text": "Az egyenlő oldalú háromszög minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "0e886268-64c4-4cfc-8e67-264865fa5cb6", "text": "Igaz", "isCorrect": true}, {"id": "a5071a8d-16b3-4adb-a9bd-c4ce8afd1630", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('917989b3-c566-4034-b92c-ead411e33479', '21feff02-016d-46e2-bb9d-c27495133b1b', '55. óra: Számonkérés', 'Számonkérés a síkbeli alakzatokból és alapszerkesztésekből (10 kérdés).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "5d07151e-a7f1-40bb-b338-00ee8c6f92eb", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "299e11ed-acfe-454c-91c7-f59e999ea0ca", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "31175f1b-7ab5-4934-9935-81a195312dae", "text": "3. Szerkeszthető-e háromszög 4 cm, 5 cm, 10 cm oldalakkal?", "type": "true-false", "options": [{"id": "35f03e08-6dd9-4d92-b360-52d9fb09cd97", "text": "Igaz", "isCorrect": false}, {"id": "349e712e-1072-4cd2-be5e-db605bff20e6", "text": "Hamis (4+5 < 10)", "isCorrect": true}], "timeLimit": 15}, {"id": "4f3a5c82-2ac1-42df-935f-8209a1dc4271", "text": "4. Ha a kör sugara 7 cm, mennyi az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "6ea47f49-12ad-48a8-bb97-8e035b425a7e", "text": "5. Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "a7517f46-2b9e-4040-85cf-64094bdc5b6a", "text": "6. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "391bf5bc-37c5-43e9-b018-080bbfa35d70", "text": "Igaz", "isCorrect": true}, {"id": "3b7828e6-311f-469c-b278-53122425e36a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "79166aa3-5699-4202-8d09-3d9312c0a4f5", "text": "7. Milyen szög a 120°-os szög?", "type": "multiple-choice", "options": [{"id": "2464c4f9-2df5-4bb9-b1c8-f4ec6e0f89cb", "text": "Tompaszög", "isCorrect": true}, {"id": "6b45f414-cd66-4139-8d61-1aaacee74a8e", "text": "Hegyesszög", "isCorrect": false}, {"id": "bbae08c0-c6f9-46e6-8852-eda5848889a2", "text": "Derékszög", "isCorrect": false}, {"id": "04d753b8-cc07-406d-a5d1-cf1453cbc1c5", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "79fbd26a-e51d-421c-be7b-02fa5aa43ff6", "text": "8. Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "3a4c5cde-9d26-460a-89ea-a88fe913d918", "text": "9. Az egybevágó alakzatok területe megegyezik.", "type": "true-false", "options": [{"id": "a973b90f-1814-46ae-8fe5-362869627762", "text": "Igaz", "isCorrect": true}, {"id": "61d16cb8-99de-4fc5-b417-dae9add8f9fe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6322ae00-8eee-4764-b687-b03315281f17", "text": "10. Hány fokosak a szabályos háromszög szögei?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e22a4023-2796-468a-9479-d1f61aed6a1b', '21feff02-016d-46e2-bb9d-c27495133b1b', '56. óra: Matematikai játékok', 'Geometriai kirakók (Tangram), alakzatok építése, stratégiák.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "40e48ccf-4bc6-4fa4-a4ae-8040e2f1f0df", "text": "Hány darabból (tanból) áll a klasszikus Tangram kirakó játék?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "b5c31ac9-9891-40bb-8424-71f6d5b8233a", "text": "Milyen síkidomokból áll a Tangram készlet?", "type": "multiple-choice", "options": [{"id": "11326cef-3272-43b8-866e-4b34ee2f5487", "text": "5 háromszög, 1 négyzet, 1 paralelogramma", "isCorrect": true}, {"id": "d323002f-e351-4ecb-b62a-73875d731263", "text": "7 négyzet", "isCorrect": false}, {"id": "28222eaf-e30c-4a94-a8a4-51774d01200c", "text": "7 kör", "isCorrect": false}, {"id": "7c11a82f-f884-4fff-ab22-f66da3d7822c", "text": "3 háromszög, 4 téglalap", "isCorrect": false}], "timeLimit": 15}, {"id": "23603a9f-5a92-4c32-8e9c-f8f5a671b229", "text": "A Tangram elemeiből sokféle figura (állatok, emberi alakok, tárgyak) kirakható.", "type": "true-false", "options": [{"id": "811fc64b-304f-4d43-b051-92c3907005fe", "text": "Igaz", "isCorrect": true}, {"id": "b0ed79e4-f5ed-4830-b1a7-9aea67e315fa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e81c7b40-bdf0-4881-b975-fcd7004fc576", "text": "A kirakós játékok fejlesztik a térszemléletet és a síkbeli alakzatok felismerését.", "type": "true-false", "options": [{"id": "821dfd86-d82f-4cf6-be69-08771ca6e229", "text": "Igaz", "isCorrect": true}, {"id": "b5097a0f-d081-4f93-8b46-7d30c18e48bf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6ae71f10-d54a-4385-8b87-cda52e595e69", "text": "A szabályos sokszögekkel hégmentesen lefedhető a sík (pl. szabályos hatoszögekkel).", "type": "true-false", "options": [{"id": "cafb7fbf-a648-4ade-bf59-e099eca5571d", "text": "Igaz", "isCorrect": true}, {"id": "65a827bb-8435-4bd7-ae41-502e3442907e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dd4c5a9f-a934-43d5-bc41-87aec22a9d8f", "text": "Hány oldala van a szabályos hexagonnak (hatszögnek)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "bac85e04-7b72-426a-bb4e-39589192cd3b", "text": "A geometriai játékok során a próbálgatás és a logikai tervezés együtt segít a megoldásban.", "type": "true-false", "options": [{"id": "a39c4e99-c14d-4b11-a2ad-611454bb0237", "text": "Igaz", "isCorrect": true}, {"id": "c8795d42-fbe3-4dd9-b76f-36114b2e44a4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1eebc01a-db54-4257-be45-1fc03a2409c7', '21feff02-016d-46e2-bb9d-c27495133b1b', '57. óra: Tengelyes tükrözés', 'Tengelyes tükrözés fogalma, tengely (t), tárgy és tükörkép (A és A'').', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "99af1394-1463-4f09-9eb5-8eca4f4d20fe", "text": "Mi a tengelyes tükrözés lényege egy ''t'' tengelyre nézve?", "type": "multiple-choice", "options": [{"id": "20e1540f-5d8f-4a50-ba5c-1cbcb948c5d1", "text": "A pont és tükörképe a tengelyre merőleges egyenesen van, és egyenlő távolságra van a tengelytől", "isCorrect": true}, {"id": "a70071ca-ce17-4c7f-b520-2964005e82b4", "text": "A pontot eltoljuk párhuzamosan", "isCorrect": false}, {"id": "1fa9fedf-f7e1-4382-be4d-9f41081d6355", "text": "A pontot elforgatjuk 180 fokkal", "isCorrect": false}, {"id": "00cf7913-fc80-44b4-a2f4-499ce35a9fdf", "text": "A pontot lefelé mozgatjuk 5 cm-rel", "isCorrect": false}], "timeLimit": 15}, {"id": "49dd03cd-ff19-48b4-aa27-ec58abc374b0", "text": "Hol van a tengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "5df9e860-e53d-4f88-8274-6c92f2f2f030", "text": "Önmagában (fixpont)", "isCorrect": true}, {"id": "c99bfbf5-4858-4dec-a5a2-36f66c746c9e", "text": "Az origóban", "isCorrect": false}, {"id": "6a1d129d-86a7-475e-b4d1-8a37db2d64fe", "text": "Végtelenben", "isCorrect": false}, {"id": "dabb3528-c4a6-41f6-9c66-2a8db92ea7f9", "text": "A tengely másik végén", "isCorrect": false}], "timeLimit": 15}, {"id": "26d4872a-67cd-481c-a12a-cce3a3bf07eb", "text": "Ha a P pont 4 cm-re van a tükörtengelytől, milyen messze van a P'' tükörkép a tengelytől?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "ea6aff5e-1637-416d-9bc8-1ec0ffba21f3", "text": "Milyen messze van a P pont a P'' tükörképétől, ha a tengelytől való távolsága 4 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "5cc97a00-bfb5-485d-b1fa-ab841d8ad17e", "text": "A tengelyes tükrözés egybevágósági transzformáció.", "type": "true-false", "options": [{"id": "a56476a4-9560-42f6-9f92-c280f3170f7c", "text": "Igaz", "isCorrect": true}, {"id": "c6c7f854-e4a1-4121-83c7-7fcf588f9c88", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b63e04e9-82e0-4bff-9160-e73dbd65ff07", "text": "A tengelyes tükrözés megváltoztatja az alakzat körüljárási irányát (pl. óramutató járásával megegyezőből ellentétes lesz).", "type": "true-false", "options": [{"id": "57d45c49-53e7-4b88-8e05-a233d8b1feb5", "text": "Igaz", "isCorrect": true}, {"id": "7df3884f-9287-4dee-9ec5-3b205ee16633", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6469ef1f-5c0c-4e1d-9e89-a472bfe24ebb", "text": "A tengelyesen tükrös alakzat és tükörképe egybevágó.", "type": "true-false", "options": [{"id": "143253f5-a35f-4f14-b279-72ba58be800c", "text": "Igaz", "isCorrect": true}, {"id": "13d380dd-fd1c-45b6-b40e-d742d09bad27", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('fa83fe91-9909-4172-bb20-016d6fa8dfff', '21feff02-016d-46e2-bb9d-c27495133b1b', '58. óra: A tengelyes tükrözés tulajdonságai', 'Távolságtartás, szögtartás, körüljárási irány megváltozása, egyenes és kör tükörképe.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "7a90b32a-3a42-40e6-99bb-d213d57d0658", "text": "Melyik tulajdonság érvényes a tengelyes tükrözésre?", "type": "multiple-choice", "options": [{"id": "2b482035-d9e2-458e-9f27-fd60ad9b6dd8", "text": "Távolságtartó, szögtartó, egyenestartó és megváltoztatja a körüljárási irányt", "isCorrect": true}, {"id": "df013edd-1ccd-4b66-b34f-91d6acf4c626", "text": "Növeli a szakaszok hosszát", "isCorrect": false}, {"id": "0a849a1a-b74c-47ae-add3-0fbe6383b455", "text": "Megváltoztatja a szögek nagyságát", "isCorrect": false}, {"id": "7aec136c-1d91-4013-8600-4bd9c319273d", "text": "Négyszögből háromszöget csinál", "isCorrect": false}], "timeLimit": 15}, {"id": "6026a334-2b69-41e9-8422-080c788613db", "text": "Egy 5 cm-es szakasz tengelyes tükörképe is 5 cm hosszú.", "type": "true-false", "options": [{"id": "ff574aa7-f284-423e-977d-43db54b82477", "text": "Igaz (távolságtartó)", "isCorrect": true}, {"id": "b0da6431-91b4-49ec-89d4-01907f0333f8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b7790b9a-21ff-407f-bf8a-33dc15e250c5", "text": "Egy 45°-os szög tengelyes tükörképe is 45°-os.", "type": "true-false", "options": [{"id": "16221528-ee34-43cd-9ae6-251b794c8aa6", "text": "Igaz (szögtartó)", "isCorrect": true}, {"id": "850275dc-e4d6-4327-8e2b-ff534feee236", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "46a61993-98b0-4b45-8258-a15ffd0c0802", "text": "A tengelyre merőleges egyenes tükörképe önmaga (önmagába transzformálódik).", "type": "true-false", "options": [{"id": "4b6277f5-3853-4a36-a93d-1dc79e45e778", "text": "Igaz", "isCorrect": true}, {"id": "b406ca89-29aa-4c64-bd0d-e3f331c21369", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9efe512e-0627-48bd-886f-900faeb5fa00", "text": "Egy kör tengelyes tükörképe ugyanolyan sugarú kör.", "type": "true-false", "options": [{"id": "ff6ba050-c1c2-44e8-a994-6a2e3ce61088", "text": "Igaz", "isCorrect": true}, {"id": "6aba7b37-ef62-4508-a9c0-4c45c93ccea6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "771b47f4-a4cd-4cce-a003-3fecedd6e075", "text": "A tengellyel párhuzamos egyenes tükörképe is párhuzamos a tengellyel.", "type": "true-false", "options": [{"id": "79dc69e4-0029-473c-a953-4468380b076a", "text": "Igaz", "isCorrect": true}, {"id": "ec393b4d-9739-465d-940c-0b81a7ddf60f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "277c0aa0-ea68-47c1-b55e-ba043ceefc7b", "text": "Hány fixpontja (helyben maradó pontja) van a tengelyes tükrözésnek a síkban?", "type": "multiple-choice", "options": [{"id": "5359a2d5-ceb6-4e63-9acb-4687956e21a0", "text": "Végtelen sok (a tükörtengely minden pontja)", "isCorrect": true}, {"id": "c1f40d35-e698-4d0b-983c-4c606da7d0eb", "text": "Csak 1", "isCorrect": false}, {"id": "78b07414-f196-43e3-af9b-9e8cf4a28dab", "text": "Nincs egy sem", "isCorrect": false}, {"id": "e7788305-2dce-4147-959a-3ea329c255a6", "text": "Pontosan 2", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c2609117-62ed-4db9-b2b3-36bd2a07862e', '21feff02-016d-46e2-bb9d-c27495133b1b', '59. óra: Gyakorlóóra', 'Tengelyes tükörkép szerkesztésének gyakorlása pontok, szakaszok, sokszögek esetén.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "6ddfdda2-22f3-4c52-96ac-13e21776b32c", "text": "Hogyan szerkesztjük meg egy P pont ''t'' tengelyre vonatkozó tükörképét?", "type": "multiple-choice", "options": [{"id": "9e3e2b45-01b3-4c76-8423-660f423a31c5", "text": "Merőlegest állítunk P-ből ''t''-re, és a talpponttól felmérjük a P távolságát a merőlegesre", "isCorrect": true}, {"id": "1a7429aa-ed61-424d-9ba1-7f5585149673", "text": "Párhuzamost húzunk ''t''-vel", "isCorrect": false}, {"id": "dd8003eb-24a7-4398-a97b-88e1fa567aa4", "text": "Körzővel kört rajzolunk P középponttal", "isCorrect": false}, {"id": "2c00cc65-b0dd-42c8-8b89-2d7440a3a425", "text": "Összekötjük P-t az origóval", "isCorrect": false}], "timeLimit": 15}, {"id": "48035e37-74d3-4a39-99b7-2249a350e3f3", "text": "Egy háromszög tengelyes tükrözése után a kapott háromszög területe megegyezik az eredetivel.", "type": "true-false", "options": [{"id": "d7ff4d86-815b-47bc-bcf7-30149bd83f50", "text": "Igaz", "isCorrect": true}, {"id": "e21d0a18-5873-4102-8a7d-cd26264f2775", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a358d5e0-21e7-44f9-ba31-14a9ff3cc9f6", "text": "Ha a P pont a tengelyen van, hol van a tükörképe?", "type": "multiple-choice", "options": [{"id": "077add83-fe91-4dc1-96ca-255d37e32cbe", "text": "Önmagában (P = P'')", "isCorrect": true}, {"id": "82ec4cee-d9e1-4295-b733-4709b15e7428", "text": "A tengely másik oldalán", "isCorrect": false}, {"id": "2d8ea4e7-e6f7-4279-995c-e103a5935f0e", "text": "A sík szélén", "isCorrect": false}, {"id": "fe3c1a08-67bd-424f-8f46-6b0403268b41", "text": "Az origóban", "isCorrect": false}], "timeLimit": 15}, {"id": "a15b2513-cdbc-4929-932f-567fecfbd6fc", "text": "A szakasz felezőmerőlegese a szakaszt önmagára tükrözi vissza.", "type": "true-false", "options": [{"id": "36539646-6664-40b8-9b80-9f72c1bbcb89", "text": "Igaz", "isCorrect": true}, {"id": "c80c0f80-61f6-4353-83dc-3158b7a6a642", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0ab684a0-650e-42c7-98c5-faae6aefdfcb", "text": "Melyik betűnek VAN függőleges szimmetriatengelye? (pl. A, M, Y, W)", "type": "multiple-choice", "options": [{"id": "bd0cbf86-a2ab-40dc-a1b6-c4155b7abd67", "text": "A", "isCorrect": true}, {"id": "f219f3a1-ad8c-451f-a1e7-484ff7202e69", "text": "F", "isCorrect": false}, {"id": "23d2b108-2206-447a-ad46-8e78f8460abd", "text": "L", "isCorrect": false}, {"id": "ce07b0fa-45f3-4199-9343-1b077c35c78f", "text": "R", "isCorrect": false}], "timeLimit": 15}, {"id": "b547db57-897c-4c6c-a17d-fb824be156a2", "text": "Melyik betűnek VAN vízszintes szimmetriatengelye? (pl. B, C, D, E, K)", "type": "multiple-choice", "options": [{"id": "683b1096-90cb-4915-8aeb-1bea4851a637", "text": "E", "isCorrect": true}, {"id": "1955cde7-7c27-4e3a-9fe4-c97346507792", "text": "F", "isCorrect": false}, {"id": "995fbb73-a22e-4371-a8b9-3d1f16e87e3f", "text": "G", "isCorrect": false}, {"id": "d22010f9-ab0b-497c-a507-3a43106cff63", "text": "J", "isCorrect": false}], "timeLimit": 15}, {"id": "399a0cfc-f1f5-43bb-a2cb-3e2c5dbf3cc3", "text": "A tengelyesen tükrös alakzatok szimmetrikusak a tükörtengelyre.", "type": "true-false", "options": [{"id": "7478fba4-1183-4c26-bf75-f7f3835e7d69", "text": "Igaz", "isCorrect": true}, {"id": "d3be2cca-97af-4bfb-9a49-1cf4fcc8232d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f17b54f3-07bc-400c-a24a-fd4c337db309', '21feff02-016d-46e2-bb9d-c27495133b1b', '60. óra: Tengelyes szimmetria', 'Tengelyesen szimmetrikus alakzatok, szögfelező és felezőmerőleges szimmetriatengelyként.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "b019b3f1-cfe8-4030-85ab-3598638eede2", "text": "Mikor nevezünk egy síkidomot tengelyesen szimmetrikusnak?", "type": "multiple-choice", "options": [{"id": "a7f7fa39-41e7-42d6-a459-3042ad7f6809", "text": "Ha van legalább egy olyan egyenes (szimmetriatengely), amelyre tükrözve a síkidom önmagába megy át", "isCorrect": true}, {"id": "9a0d7063-14f1-4869-b77d-bc4924f49d85", "text": "Ha minden oldala egyenlő", "isCorrect": false}, {"id": "4e74ad1d-8dee-4a62-8920-0e3c84b02e32", "text": "Ha kerek", "isCorrect": false}, {"id": "e703d8c9-8c3b-4a38-a6ab-9d8608f7e460", "text": "Ha nincs szöge", "isCorrect": false}], "timeLimit": 15}, {"id": "80861ffe-53ad-43b7-8d9d-92e3b912c13b", "text": "Mi a szögfelező egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "12ad0652-3aad-4d7d-8d3d-862bac0508a9", "text": "A szögtartományt két egyenlő szögre osztja, és pontjai egyenlő távolságra vannak a szög száraitól", "isCorrect": true}, {"id": "4027f9ac-8363-44c1-a55a-560da7df67d0", "text": "A szög szárait meghosszabbítja", "isCorrect": false}, {"id": "19a80af0-1faa-4c4f-9f72-a9b0cc7a15d7", "text": "Merőleges a szög száira", "isCorrect": false}, {"id": "d97bb047-7255-4b62-a20c-01d52a43c8ff", "text": "Párhuzamos a szög száival", "isCorrect": false}], "timeLimit": 15}, {"id": "f8fcff96-41ef-4b03-9459-25ba0d5df318", "text": "A szögfelező egyenes a szög szimmetriatengelye.", "type": "true-false", "options": [{"id": "51a2b1e3-b110-4b98-a8be-0b9e5bba6993", "text": "Igaz", "isCorrect": true}, {"id": "e0494c56-22c5-4e48-aacd-0064aad3adb9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "706ef36a-f5e1-4acc-88bc-64eb09c5dbf6", "text": "Hány szimmetriatengelye van egy 60°-os szögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "aa72c0ed-9a47-4a8c-8bc0-d5c92d1aac9c", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "b34a239f-c53c-437b-9cdd-c21c12a05cba", "text": "Végtelen sok (minden középponton átmenő egyenes)", "isCorrect": true}, {"id": "591e1da4-8623-4bc0-9b15-fcae73fcad0a", "text": "1", "isCorrect": false}, {"id": "7b5e0065-36ca-4f6e-9548-73ddd2370e24", "text": "2", "isCorrect": false}, {"id": "dc2c4910-14f2-42df-8d59-672d829b2b4c", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "9b509fd6-9933-411b-8581-074766938d6a", "text": "A szögfelező megszerkesztéséhez körzőíveket használunk a szög szárain.", "type": "true-false", "options": [{"id": "b1f6c7a2-f723-4e36-85e2-c1e06eea1169", "text": "Igaz", "isCorrect": true}, {"id": "0d46384e-ece9-4d5b-8e7c-c05d8c35ffa1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8edb992b-8eff-46ba-a031-1f2c18aea277", "text": "Hány fokos két 30°-os részre osztja a szögfelező a 60°-os szöget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;